    if (!inside || !closeup) return; const st = inside.steps[inside.i], el = insideElapsed(now), q = inside.svg;
    if (inside.path) inside.pos = along(inside.path, ease(prog(el, 0, inside.dur)));
    const dot = q.querySelector('.ixdot'), glow = q.querySelector('.ixglow'), p = inside.pos;
    [dot, glow].forEach(c => { c.style.display = p ? '' : 'none'; if (p) { c.setAttribute('cx', p[0]); c.setAttribute('cy', p[1]); } });
    glow.setAttribute('r', 22 + 6 * Math.abs(Math.sin(now / 320)));
