    { const atEnd = idx === PAUSES.length - 1 && !moving() && t >= EC - 0.2;
      const v = IDLE ? 'idle' : (atEnd ? 'end' : (TRS.some(tr => camP(tr, t) > 0.5) ? 'zoom' : 'arch'));
      if (EMBED && v !== window.__view) { window.__view = v; toParent(v === 'end' ? { type: 'view', view: v, auto: mode !== 'step' } : { type: 'view', view: v }); } }
    if (!IDLE && idx === FIRST && !moving()) E('cap').style.display = 'none';   // the start hint takes the caption's place
    E('cap').style.maxWidth = (IDLE || !bar.offsetLeft ? 1130 : Math.max(560, bar.offsetLeft - 36 - 28)) + 'px';
    startHint.style.display = (!IDLE && idx === FIRST) ? 'block' : 'none';
    endBar.style.display = (!IDLE && idx === PAUSES.length - 1 && !moving()) ? 'flex' : 'none';
    ctr.textContent = `${idx + 1 - FIRST} / ${PAUSES.length - FIRST}`;
    E('bPrev').disabled = idx === FIRST || !!closeup; E('bNext').disabled = idx === PAUSES.length - 1 || !!closeup;
